package com.playsphere.payment;
import tools.jackson.databind.JsonNode;import com.playsphere.config.AppProperties;import java.nio.charset.StandardCharsets;import java.util.Base64;import java.util.Map;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component @ConditionalOnProperty(prefix="app.payment",name="provider",havingValue="razorpay")
public class RazorpayPaymentGateway implements PaymentGateway{
 private final RestClient client;private final AppProperties.Payment config;public RazorpayPaymentGateway(RestClient.Builder b,AppProperties p){config=p.payment();String auth=Base64.getEncoder().encodeToString((config.razorpay().keyId()+":"+config.razorpay().keySecret()).getBytes(StandardCharsets.UTF_8));client=b.baseUrl("https://api.razorpay.com/v1").defaultHeader(HttpHeaders.AUTHORIZATION,"Basic "+auth).build();}
 public GatewayOrder createOrder(Payment p){JsonNode n=client.post().uri("/orders").contentType(MediaType.APPLICATION_JSON).body(Map.of("amount",p.getAmount().movePointRight(2).longValueExact(),"currency","INR","receipt",p.getId())).retrieve().body(JsonNode.class);return new GatewayOrder("RAZORPAY",n.path("id").asString(),false,null);}public void refund(Payment p,java.math.BigDecimal amount){client.post().uri("/payments/{id}/refund",p.getProviderPaymentId()).contentType(MediaType.APPLICATION_JSON).body(Map.of("amount",amount.movePointRight(2).longValueExact())).retrieve().toBodilessEntity();}
}
